/**
 * とにお実験台帳 — この世にない試みの記録
 *
 * ■ 方針
 * ここに載るのは「他所に前例を探せなかった仕組み」だけ。改良は載せない。発明だけ載せる。
 * 実験は失敗する前提で複数走らせる。失敗したら status を failed にして、死因を log に書く。
 * 消さない。失敗の記録は、この世界の通貨(失った者が、報酬を受け取る)である。
 *
 * ■ status の意味
 *   live   = 稼働中。すでに世界の一部
 *   armed  = 装填済み。次の実戦(レッスン/号/夜)で発火する
 *   gated  = 実装済みだが、条件が満たされるまで起動しない
 *   failed = 死亡。死因記録あり。墓は残す
 *   won    = 成功条件を満たした
 */

export type ExperimentStatus = 'live' | 'armed' | 'gated' | 'failed' | 'won';

export interface Experiment {
    id: string;
    name: string;
    /** 何が「この世にない」のか。1文で言えなければ実験ではない */
    novelty: string;
    hypothesis: string;
    method: string;
    successCriteria: string;
    failureMode: string;
    status: ExperimentStatus;
    log: string[];
}

