export function experimentsByStatus(status: ExperimentStatus): Experiment[] {
    return EXPERIMENTS.filter((e) => e.status === status);
}

export const EXPERIMENT_LEDGER = {
    total: EXPERIMENTS.length,
    live: EXPERIMENTS.filter((e) => e.status === 'live').length,
    armed: EXPERIMENTS.filter((e) => e.status === 'armed').length,
    gated: EXPERIMENTS.filter((e) => e.status === 'gated').length,
    failed: EXPERIMENTS.filter((e) => e.status === 'failed').length,
    won: EXPERIMENTS.filter((e) => e.status === 'won').length,
    note: '失敗の墓は消さない。won が1つ出れば、残り全部の failed は肥料だったことになる。',
};
